// Secciones permanentes: encuentros y directorio con mapa propio.
const meetingRoutes=(m,origin)=>`${ext(directionLink(origin,m.key,'driving'),'Ruta en taxi','button')}${ext(directionLink(origin,m.key,'transit'),'Alternativa en transporte público','text-link')}`;
$('#encuentros').innerHTML=`<div class="section-heading"><p class="eyebrow">SÁBADO · DOMINGO · LUNES</p><h2>Nos vemos aquí.</h2><p>Un punto concreto para cada día, al que ambas parejas pueden llegar por su cuenta. Las salidas principales están calculadas para taxi; la alternativa en transporte público incluye una salida más temprana.</p></div><div class="meeting-cards">${meetups.map(m=>`<article class="meet-card" id="encuentro-${m.day}"><header><span class="meet-date">${m.weekday}<b>${m.day}</b> OCT</span><div><p class="eyebrow">${m.time} · HORA DE COLOMBIA</p><h3>${m.title}</h3><p>${m.address}</p></div></header><div class="exact-spot"><b>El punto exacto</b><p>${m.spot}</p>${placeLink(m.key,'Abrir el mismo punto para las dos parejas')}</div><p class="meet-why">${m.why}</p><div class="meet-origins">${[['hotel','Hampton · Rafy y Vanessa'],['airbnb','Airbnb · Germán y Lina']].map(([key,title])=>`<div><h4>${title}</h4><p class="leave-time">Salir a las ${m[key].leave} · en taxi</p><p>${m[key].taxi}</p>${meetingRoutes(m,key)}<details><summary>Si preferimos metro / tranvía</summary><p>${m[key].transit}</p></details></div>`).join('')}</div><div class="meet-next"><p><b>Después del encuentro</b><br>${m.onward}</p><p><b>Regreso</b><br>${m.return}</p></div><div class="meet-links"><a href="#dia-${m.day}">Ver el día completo →</a>${ext(m.source,'Referencia del lugar')}</div></article>`).join('')}</div><p class="fine">Propuestas de coordinación, no reservas de transporte. Los tiempos son márgenes de planificación, no tráfico en vivo. Consultar la ruta al salir; quien llegue primero envía una foto y permanece en el punto acordado. Si llueve, avisarse antes de cambiar de acceso.</p>`;

const categoryNames={M:'Miradores',R:'Restaurantes',X:'Mercados'};
$('#guia').innerHTML=`<div class="section-heading"><p class="eyebrow">LA CIUDAD A MANO</p><h2>Sabores, mercados y vistas.</h2><p>Los lugares del itinerario y algunas alternativas para elegir sobre la marcha. Los códigos de las fichas coinciden con los del mapa: <b>M</b> miradores, <b>R</b> restaurantes y <b>X</b> mercados.</p></div><div class="guide-controls" aria-label="Filtrar lugares"><button type="button" data-filter="all" class="active" aria-pressed="true">Todos · ${directory.length}</button>${Object.entries(categoryNames).map(([k,v])=>`<button type="button" data-filter="${k}" aria-pressed="false"><span class="category-code cat-${k}">${k}</span> ${v} · ${directory.filter(x=>x.type===k).length}</button>`).join('')}</div><div class="guide-map-wrap"><div id="directory-map" role="region" aria-label="Mapa de todos los miradores, restaurantes y mercados"></div><button type="button" id="fit-directory" class="button">Ver todos los lugares visibles ⤢</button></div><p class="fine">H = Hampton · B ≈ cuadra del Airbnb. Los marcadores ubican lugares o sectores de forma orientativa. Para la puerta exacta, abre la navegación por nombre y dirección. Las Palmas es un sector sin establecimiento elegido. La Octava y Colosal combinan mirador y restaurante y aparecen una sola vez, como M.</p><p id="guide-status" class="guide-status" aria-live="polite"></p><div class="guide-cards">${directory.map(v=>`<article class="guide-card" data-category="${v.type}" id="ficha-${v.id}"><header><span class="category-code cat-${v.type}">${v.id}</span><div><p class="eyebrow">${v.area}</p><h3>${v.name}</h3></div>${v.rating?`<span class="rating">★ ${v.rating}<small>Guía anterior</small></span>`:''}</header><p class="venue-address">${v.address}</p><p>${v.description}</p><dl><dt>Cómo encaja</dt><dd>${v.visit}</dd><dt>Horario y disponibilidad</dt><dd>${v.hours}</dd><dt>Consejo para ustedes</dt><dd>${v.tip}</dd></dl><div class="venue-links"><button type="button" class="button light" data-show-place="${v.id}">Ver ${v.id} en el mapa</button>${placeLink(v.key,'Cómo llegar')}${v.url?ext(v.url,esc(v.label)):''}${v.extra?ext(v.extra,v.key==='octava'?'Carta del restaurante':'Web del parque'):''}</div></article>`).join('')}</div><p class="fine">Consulta de páginas: 20 de septiembre de 2026. Las estrellas proceden de las guías anteriores y no son un ranking actualizado; no se asignan puntuaciones donde no hay datos comparables. Los tiempos de visita y consejos son propuestas de esta guía. Los locales adicionales son alternativas, no compromisos añadidos al itinerario.</p>`;

let directoryMap=null;
const directoryMarkers=new Map();
const visibleVenues=new Set(directory.map(v=>v.id));
function directoryBounds(){if(!directoryMap)return;const points=[places.hotel.p,places.airbnb.p,...directory.filter(v=>visibleVenues.has(v.id)).map(v=>places[v.key].p)];directoryMap.fitBounds(points,{padding:[35,35],maxZoom:14});}
function filterDirectory(type){
 document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===type;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 visibleVenues.clear();
 directory.forEach(v=>{const show=type==='all'||v.type===type;document.getElementById('ficha-'+v.id).hidden=!show;if(show)visibleVenues.add(v.id);const marker=directoryMarkers.get(v.id);if(marker&&directoryMap){if(show)marker.addTo(directoryMap);else directoryMap.removeLayer(marker);}});
 $('#guide-status').textContent=`${visibleVenues.size} lugares · ${type==='all'?'todas las categorías':categoryNames[type]}`;
 directoryBounds();
}
if(window.L){
 directoryMap=L.map('directory-map',{scrollWheelZoom:false});
 const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(directoryMap);
 tiles.once('tileerror',()=>{$('#directory-map').insertAdjacentHTML('afterend','<p class="fine">No se pudo cargar parte de la cartografía. Las fichas y sus enlaces de navegación siguen disponibles.</p>');});
 const venueIcon=(label,kind)=>L.divIcon({className:'guide-pin '+kind,html:`<span>${label}</span>`,iconSize:[39,36],iconAnchor:[19,18]});
 for(const [key,label,kind] of [['hotel','H','base-h'],['airbnb','B≈','base-b']]){const p=places[key];L.marker(p.p,{icon:venueIcon(label,kind),title:p.name}).addTo(directoryMap).bindPopup(`<b>${esc(p.name)}</b>${p.note?'<p>'+esc(p.note)+'</p>':''}<p>${placeLink(key,'Navegar al alojamiento')}</p>`);}
 L.circle(places.airbnb.p,{radius:120,color:'#ad5733',fillOpacity:.09,weight:1,dashArray:'4 4',interactive:false}).addTo(directoryMap);
 for(const v of directory){const p=places[v.key];const marker=L.marker(p.p,{icon:venueIcon(v.id,'cat-'+v.type),title:`${v.id} · ${v.name}`}).bindPopup(`<b>${esc(v.id+' · '+v.name)}</b><p>${esc(v.address)}</p><p>${esc(v.visit)}</p><p>${placeLink(v.key,'Cómo llegar')}</p><a href="#ficha-${v.id}">Ver la ficha completa ↓</a>`).addTo(directoryMap);directoryMarkers.set(v.id,marker);}
 $('#fit-directory').onclick=directoryBounds;
 directoryBounds();
}else{
 $('#directory-map').innerHTML='<p class="map-error">El mapa no está disponible. Puedes consultar todos los lugares y abrir la navegación desde sus fichas.</p>';
 $('#fit-directory').hidden=true;
}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>filterDirectory(b.dataset.filter));
document.querySelectorAll('[data-show-place]').forEach(b=>{b.onclick=()=>{if(!directoryMap)return;const v=directory.find(x=>x.id===b.dataset.showPlace);directoryMap.setView(places[v.key].p,15);directoryMarkers.get(v.id).openPopup();$('#directory-map').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});};if(!directoryMap)b.hidden=true;});
filterDirectory('all');
